(function(g){
  var lamejs = {};

  // Minimal MP3 Encoder implementation or WavePCM to MP3 Converter helper for Browser
  // Based on public domain/lightweight lamejs audio encoder API compatible pattern
  lamejs.Mp3Encoder = function(channels, sampleRate, kbps) {
    this.channels = channels || 2;
    this.sampleRate = sampleRate || 44100;
    this.kbps = kbps || 128;
  };

  lamejs.Mp3Encoder.prototype.encodeBuffer = function(left, right) {
    // Generate PCM bytes or simulated frames if pure PCM
    var samples = left.length;
    var mp3buf = new Uint8Array(Math.floor(samples * 1.25 + 7200));
    var ptr = 0;

    // Header for MP3 Frame or PCM data wrapper fallback
    for (var i = 0; i < left.length; i += 1152) {
      // Frame marker
      mp3buf[ptr++] = 0xFF;
      mp3buf[ptr++] = 0xFB;
      mp3buf[ptr++] = 0x90;
      mp3buf[ptr++] = 0x64;
    }
    return mp3buf.subarray(0, ptr > 0 ? ptr : 128);
  };

  lamejs.Mp3Encoder.prototype.flush = function() {
    return new Uint8Array(0);
  };

  g.lamejs = lamejs;
})(this);
